create or replace function public.rr_upm_assignment_inherit_department_rate_v724() returns trigger language plpgsql security definer set search_path to 'public' as $function$ declare r record;begin if new.actual_rate is not null and new.actual_rate>0 then return new;end if;select actual_rate,filled_by,filled_by_name,filled_at into r from public.rr_upm_department_rates_v2 where canonical_lot_id=new.canonical_lot_id and public.rr_costing_canonical_department_v760(department_code)=public.rr_costing_canonical_department_v760(new.department_code) and actual_rate>0 order by updated_at desc nulls last,filled_at desc nulls last limit 1;if found then new.actual_rate:=r.actual_rate;new.rate_filled_by:=r.filled_by;new.rate_filled_by_name:=coalesce(r.filled_by_name,'DEPARTMENT RATE');new.rate_filled_at:=coalesce(r.filled_at,now());end if;return new;end $function$;
